export const handlePercentage = (value) => {
  const isDecimal = value !== 'None' && value % 1 !== 0;
  return isDecimal
    ? `${value && value.toFixed(2)}%`
    : value !== 'None'
    ? `${value}%`
    : '-';
};

export const handleTimeFormat = (date) => {
  let value;
  const minutes = moment().diff(date, 'minutes');
  const minPerYear = 24 * 365 * 60;
  const minPerMonth = 24 * 30 * 60;
  const minPerDay = 24 * 60;
  const minPerHour = 60;
  if (minutes > 60) {
    const years = Math.floor(minutes / minPerYear);
    const month = Math.floor(minutes / minPerMonth);
    const day = Math.floor(minutes / minPerDay);
    const hour = Math.floor(minutes / minPerHour);
    if (years > 0) {
      value = `${years} year${years > 1 ? 's' : ''} ago `;
    } else if (month > 0) {
      value = `${month} month${month > 1 ? 's' : ''} ago`;
    } else if (day > 0) {
      value = `${day} day${day > 1 ? 's' : ''} ago`;
    } else if (hour > 0) {
      value = `${hour} hour${hour > 1 ? 's' : ''} ago`;
    }
  } else {
    value =
      minutes === 0
        ? 'just now'
        : `${minutes} minute${minutes > 1 ? 's' : ''} ago`;
  }
  return value;
};

