export const separateName = (value, screenRenamedList) => {
  const name =
    value?.name && typeof value?.name === 'string'
      ? value?.name
      : value?.name && Array.isArray(value?.name[0]?.value) &&
        value?.name[0]?.value?.map((v) => `${screenRenamedList[v] || v}`);
  return name && typeof name !== 'string'
    ? name.toString().replace(/,/g, '<i>&nbsp;or</i> <br/>')
    : name;
};

export const selectName = (value, screenRenamedList) => {
  const name =
    value?.name && typeof value?.name === 'string'
      ? value?.name
      : value?.name &&  Array.isArray(value?.name[0].value) &&
        value?.name[0].value.map(
          (v, index, list) =>
            `${screenRenamedList[v] || v} ${
              index < list.length - 1 ? 'or ' : ''
            }`
        );
  return name && typeof name !== 'string'
    ? name.toString().replace(/,/g, '')
    : name;
};

export const separateArrayName = (value, renameScreen) => {
  const name =
    value instanceof Array
      ? value.map((v, index, list) => `${renameScreen[v] || v}`)
      : value;
  return name && typeof name !== 'string'
    ? name.toString().replace(/,/g, '<i>&nbsp;or</i> <br/>')
    : name;
};

export const selectedValue = (value) => {
  const name =
    value instanceof Array
      ? value.map(
          (v, index, list) => `${v} ${index < list.length - 1 ? 'or ' : ''}`
        )
      : value;
  return name instanceof Array ? name.toString().replace(/,/g, '') : name;
};

