export const secondsToTime = (secs) => {
  const hours = Math.floor(secs / (60 * 60));
  const divisor_for_minutes = secs % (60 * 60);
  const minutes = Math.floor(divisor_for_minutes / 60);
  const divisor_for_seconds = divisor_for_minutes % 60;
  const seconds = Math.floor(divisor_for_seconds);

  return `${
    (hours !== 0 ? hours : '') +
    (hours !== 0 ? ':' : '') +
    (minutes >= 10 ? minutes : +minutes)
  }:${seconds >= 10 ? seconds : `0${seconds}`}`;
};

export const timeFormatToSecond = (time) => {
  let newTime;
  // format: 09
  if (/^\d+$/.test(time)) {
    // re-format to: 0:0:09
    newTime = `0:0:${time}`;
  }
  // format: 1:09
  if (/^\d+:\d+$/.test(time)) {
    // re-format to: 0:1:09
    newTime = `0:${time}`;
  }
  if (/^\d?\d:\d+:\d+$/.test(time)) {
    newTime = `${time}`;
  }
  const timeFormat = newTime?.split(':');
  if (timeFormat) {
    // calculating to get seconds
    return +timeFormat[0] * 60 * 60 + +timeFormat[1] * 60 + +timeFormat[2];
  }
  return undefined;
};

