export const compactNotation = (number, precision = 1) => {
  const abbrev = ['', 'K', 'M', 'B', 'T'];
  const unRamifiedOrder = Math.floor(Math.log10(Math.abs(number)) / 3);
  const order = Math.max(0, Math.min(unRamifiedOrder, abbrev.length - 1));
  const suffix = abbrev[order];
  return round(number / (10 ** (order * 3)), precision) + suffix;
};

export const convertGetTime = ({ durationInSecs, roundFalse } = {}) => {
  let value;
  const seconds = roundFalse ? durationInSecs : round(durationInSecs);
  if (durationInSecs < 60) return `${Math.round(durationInSecs)} sec`;
  if (seconds > -1) value = formattedTime(seconds);
  else value = 0;
  return value;
};
export function consecutiveRanges(indexList) {
  let length = 1;
  const list = [];
  // traverse the array from first position
  for (let i = 1; i <= indexList.length; i++) {
    // check the difference between the current and the previous elements If the difference doesn't equal to 1 just increment the length variable.
    if (i === indexList.length || indexList[i] - indexList[i - 1] !== 1) {
      // if the range contains only one element. add it into the list.
      if (length === 1) {
        list.push(indexList[i - length].toString());
      } else {
        // build the range between the first element of the range and the current previous element as the last range.
        list.push(`${indexList[i - length]} -> ${indexList[i - 1]}`);
      }
      // after finding the first range initialize the length by 1 to build the next range.
      length = 1;
    } else {
      length++;
    }
  }
  return list;
}
