export const preciseNumber = (number, precision, isTooltip) => {
  if (typeof number !== 'number') return 0;
  if (number === 0) return 0;
  let numberCopy = number;
  const abs = Math.abs(numberCopy);
  numberCopy = abs;
  const digits = Math.ceil(Math.log(numberCopy) / Math.LN10);
  const factor = 10 ** (isTooltip ? 4 : (precision - digits)); // CX-1904 If tooltip, show 4 decimal values
  let result = numberCopy * factor;
  result = Math.round(result, 0);
  return result / factor;
};

