export const getBoxDataPercentage = (currentValueRaw, prevValueRaw) => {
    const currentValue = currentValueRaw || 0;
    const prevValue = prevValueRaw || 0;
    if (prevValue === 0 && currentValue > 0) return 'Infinity';
    if (prevValue === 0 && currentValue === 0) return 'NaN'
    const percentNumerical = Math.round(((currentValue - prevValue) / prevValue) * 100, 2)
    return percentNumerical > 0 ? `+${percentNumerical}` : `${percentNumerical}`;
}

