export const validateInputName = (input) => {
  const isValidInput = nameRegex.test(input);
  
  if (!isValidInput) {
    return `Name field only accepts the following characters: alphabets (A-Z, a-z), numbers (0-9), dash (-), underscore (_), apostrophe ('), and spaces.`;
  } if (input.length >= 32) {
    return 'Name should contain at most 32 characters.';
  }
  return ''
}

export const ordinalSuffixOf = (i) => {
  const j = i % 10;
    const k = i % 100
  if (j === 1 && k !== 11) {
    return `${i  }st`
  }
  if (j === 2 && k !== 12) {
    return `${i  }nd`
  }
  if (j === 3 && k !== 13) {
    return `${i  }rd`
  }
  return `${i  }th`
}

