export const handleErrorMessage = (errorResponse) => {
  let alertErr = 'Something bad happened! Please try again later';
  if (errorResponse.data !== ' ') {
    if (errorResponse.data.error.message) {
      alertErr = errorResponse.data.error?.message;
      if (alertErr && alertErr.includes('suspicious behavior')) {
        changeCommonValue('isVisible_custom_popup', true);
      }
    } else if (errorResponse.data.error.email) {
      [alertErr] = errorResponse.data.error.email;
    } else if (errorResponse.data.error.name) {
      [alertErr] = errorResponse.data.error.name;
    } else if (errorResponse.data.error.companyName) {
      [alertErr] = errorResponse.data.error.companyName;
    } else if (errorResponse.data.error.password){
      [alertErr] = errorResponse.data.error.password;
    } else if (errorResponse.data.error.phone) {
      [alertErr] = errorResponse.data.error.phone;
    }
  }
  message.error(alertErr);
}

