export const convertFileToBase64 = (file) => {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.readAsDataURL(file);

    reader.onload = () => resolve(reader.result);
    reader.onerror = (error) => reject(error);
  });
};

export const findCategoryTitle = (value, dropdown) => {
  if(!dropdown || !value) return null;
  return Object.entries(dropdown)
      .flatMap(([category, items]) => items.map(item => ({ ...item, categoryTitle: category })))
      .find(item => item.attribute === value)?.categoryTitle || null;
};