  static async switchToLegacy(data) {
    return axiosInstance({
      method: 'POST',
      url: `${process.env.API_URL}/switch-to-legacy-dashboard`,
      data,
      withCredentials: true,
      validateStatus(status) {
        return status >= 200 && status <= 302;
      },
    });
  }

  static async inviteToSwitch() {
    return axiosInstance({
      method: 'POST',
      url: `${process.env.API_URL}/dashboard/invite-all-collaborators `,
      withCredentials: true,
    });
  }

  static async completeOnboarding(data) {
    return axiosInstance({
      method: 'PUT',
      url: `${process.env.API_URL}/profile/update-onboarding-status`,
      data,
      withCredentials: true,
    });
  }

  static async getCollaborator() {
    const res = await axiosInstance.get(
      `${process.env.API_URL}/dashboard/has-collaborators`,
      { withCredentials: true }
    );
    return res;
  }

  static async profileNewEmail(data) {
    return axiosInstance({
      method: 'PUT',
      url: `${process.env.API_URL}/profile/new-email`,
      data,
      withCredentials: true,
      validateStatus(status) {
        return status >= 200 && status <= 302;
      },
    });
  }

  static async uploadImage(data) {
    return await axiosInstance({
      method: 'POST',
      url: `${process.env.AUTH_API_URL}/user/profile/update-image`,
      data,
      withCredentials: true,
      validateStatus(status) {
        return status >= 200 && status < 401;
      },
    });
  }
