interface FormData {
	organizationName: string;
	mobileAppsList: string;
	webDomainsList: string;
}

const API_ID = process.env.FLOW_ADD_APP_ID;

export const focusInput = (name: string, useCustomSelector = false) => {
	setTimeout(() => {
		const input = document.querySelector(useCustomSelector ? name : `[name="${name}"]`) as HTMLInputElement
		if (input) {
			input.focus()
		}
	}, 200)
}

const processUrlValue = (value: string): string => {
	let processedValue = value.trim();

	processedValue = processedValue.replace(/^https?:\/\//, '');
	processedValue = processedValue.replace(/^www\./, '');
	const [domain] = processedValue.split('/');
	processedValue = domain;
	const parts = processedValue.split('.');
	const cleanParts = [...parts];
	
	if (cleanParts.length > 1 && cleanParts[cleanParts.length - 1].length === 2) {
		cleanParts.pop();
	}
	
	if (cleanParts.length > 1) {
		const lastPart = cleanParts[cleanParts.length - 1];
		const commonTlds = ['com', 'org', 'net', 'edu', 'gov', 'mil', 'int', 'biz', 'info', 'name', 'pro', 'museum', 'coop', 'aero', 'co', 'io', 'ai', 'app', 'dev', 'tech', 'online', 'site', 'website', 'store', 'blog', 'news', 'tv', 'me', 'ly'];
		if (commonTlds.includes(lastPart.toLowerCase())) {
			cleanParts.pop();
		}
	}
	
	if (cleanParts.length >= 1) {
		processedValue = cleanParts[cleanParts.length - 1];
	}
	
	return processedValue.trim();
};

const getAppValue = (val: string, isWeb = false) => {
	const hasMultipleEntries = val.includes(',');
	if (!hasMultipleEntries && val.trim()) {
		let processedName = val.trim();
		
		if (isWeb) {
			processedName = processUrlValue(processedName);
		}
		
		return processedName
	}
	return null
}
const OrganizationApps = () => {
	const [form] = Form.useForm<FormData>();
	const { formData, setValues } = useFormData();
	const { setPage } = usePageState();
	const dispatch = useDispatch();
	const [loading, setLoading] = React.useState(false)
	const [mobileAppError, setMobileAppError] = React.useState<string | null>(null)
	const [webAppError, setWebAppError] = React.useState<string | null>(null)
	const [platformsError, setPlatformsError] = React.useState<string | null>(null)
	const recaptchaRef = React.useRef<ReCAPTCHA>(null)
	const hasMobileApp = !!Form.useWatch('mobileApps', form)
	const hasWebApp = !!Form.useWatch('webApps', form)
	const hasAnyApps = !!hasMobileApp || !!hasWebApp
	const mobileAppsList = Form.useWatch('mobileAppsList', form)
	const webDomainsList = Form.useWatch('webDomainsList', form)

	const handleSaveValue = React.useCallback((values: FormData) => {
		// eslint-disable-next-line no-shadow
		const { mobileAppsList, webDomainsList } = values
		if (hasAnyApps) {
			let mobileVal
			let webVal
			if (mobileAppsList) {
				mobileVal = getAppValue(mobileAppsList)
			}
			if (webDomainsList) {
				webVal = getAppValue(webDomainsList, true)
			}
			
			const signupAppData = {
				mobile: mobileVal,
				web: webVal
			}
			try {
				localStorage.setItem('signupApp', JSON.stringify(signupAppData));
			} catch (err) {
				// silent fail
			}
		}
	}, [hasAnyApps]);

	React.useEffect(() => {
		setPlatformsError(null)
		setMobileAppError(null)
		setWebAppError(null)
	}, [hasMobileApp, hasWebApp])

	const shouldFocusOnFirstInput = React.useRef(true)
	React.useEffect(() => {
		if (shouldFocusOnFirstInput?.current) {
			focusInput('organizationName')
			shouldFocusOnFirstInput.current = false
		}
	}, [])

	const handleBack = React.useCallback(() => {
		setPage(0)
	}, [setPage])

	const onFinish = React.useCallback(async (values: FormData) => {
		setLoading(true)
		const { organizationName: orgName } = values
		let appType;

		if (hasMobileApp && hasWebApp) {
			appType = 'mobile;web'
		} else if (hasMobileApp) {
			appType = 'mobile'
		} else {
			appType = 'web'
		}

		setKeyByValue('onBoardVisible', true)
		setKeyByValue('isActivation', false)

		window.dataLayer = window.dataLayer || []
		window.dataLayer.push({
			event: 'Sign Up Step 2 Submission',
		})

		await hubspot.submitForm({
			mobile_apps: mobileAppsList || '',
			web_domains: webDomainsList || '',
			app_type: appType,
			organization_name: orgName,
			email: formData?.email || '',
		}, API_ID)
			.catch((err) => rollbar.error(err))

		handleSaveValue(values)

		const token = await recaptchaRef.current?.executeAsync()
		dispatch(trackPageViews(null, {
			eventName: 'wa_signup_org_submitted',
			eventProperty: {
				email: formData?.email || '',
				orgName: values?.organizationName || '',
			},
		}, token ))

		if (setPage) {
			setPage((currentPage) => (currentPage || 0) + 1);
		}
		if (setValues) {
			setValues({
				organizationName: orgName,
				mobileAppsList,
				webDomainsList,
			});
		}
		setLoading(false)
	}, [hasMobileApp, hasWebApp, setPage, setValues, formData?.email, mobileAppsList, webDomainsList, dispatch, handleSaveValue])

	return (
		<>
			<ReCAPTCHA
				ref={recaptchaRef}
				size="invisible"
				sitekey={process.env.SITE_KEY || ''}
			/>
			<FlowLayout
				title="Tell us about your company."
				progress={33}
				hideLogos
			>	
				<FlowWrapper>
					<Form
						form={form}
						onFinish={onFinish}
						layout="vertical"
						autoComplete="off"
						noValidate
						validateTrigger={['onSubmit']}
						initialValues={{
							organizationName: formData?.organizationName,
							mobileAppsList: formData?.mobileAppsList,
							webDomainsList: formData?.webDomainsList,
							mobileApps: formData?.mobileAppsList?.length,
							webApps: formData?.webDomainsList?.length,
						}}
					>
						<FormWrapper>
							<SectionHeader>
								Enter organization name
							</SectionHeader>
							<TextInput
								name="organizationName"
								ariaLabel='organization name input'
								placeholder='Your Company Inc.'
								disabled={loading}
								rules={[
									{
										validator: (_, value) => {
											if (!value?.length) {
												focusInput('organizationName')
												return Promise.reject(new Error('Organization name is required'))
											}
											if (!nameRegex.test(value)) {
												focusInput('organizationName')
												return Promise.reject(new Error("Name field only accepts the following characters: alphabets (A-Z, a-z), numbers (0-9), dash (-), underscore (_), apostrophe ('), and spaces."))
											}
											if (value.length > 32) {
												focusInput('organizationName')
												return Promise.reject(new Error('Organization name should contain at most 32 characters.'))
											}
											return Promise.resolve()
										}
									}
								]}
							/>
							<SectionHeader>
								Select platforms to track
							</SectionHeader>
							<PlaformOptionsContainer>
								<PlatformOptionButtons>
									<Buttons>
									<PlatformOptionButton>
										<Form.Item
											name="mobileApps"
											id="mobileApps"
											initialValue={false}
											valuePropName='checked'
											validateTrigger={['onSubmit']}
											rules={[{
												validator: () => {
													if (hasMobileApp && !mobileAppsList?.length) {
														setMobileAppError('This field is required')
														return Promise.reject()
													}
													return Promise.resolve()
												}
											}]}
										>
											<Checkbox
												type="checkbox"
												disabled={loading}
											/>
										</Form.Item>
										<ButtonCheckbox
											htmlFor="mobileApps"
											tabIndex={0}
											aria-checked={hasMobileApp}
											onClick={() => {
												if (!hasMobileApp) {
													setTimeout(() => focusInput('mobileAppsList'), 50);
												}
											}}
										>
											<span>
												<img src="/static/mobile-app.svg" alt="Mobile App" />
												Mobile App
											</span>
										</ButtonCheckbox>
									</PlatformOptionButton>
									<PlatformOptionButton>
										<Form.Item
											name="webApps"
											id="webApps"
											valuePropName='checked'
											initialValue={false}
											validateTrigger={['onSubmit']}
											rules={[{
												validator: () => {
													if (!hasWebApp && !hasMobileApp) {
														setPlatformsError('Select at least one platform to track')
														return Promise.reject()
													}
													if (hasWebApp && !webDomainsList?.length) {
														setWebAppError('This field is required')
														return Promise.reject()
													}
													return Promise.resolve()
												}
											}]}
										>
											<Checkbox
												type="checkbox"
												disabled={loading}
												id="webApps"
											/>
										</Form.Item>
										<ButtonCheckbox
											htmlFor="webApps"
											tabIndex={0}
											aria-checked={hasWebApp}
											onClick={() => {
												if (!hasWebApp) {
													setTimeout(() => focusInput('webDomainsList'), 50);
												}
											}}
										>
											<span>
												<img src="/static/web-app.svg" alt="Website or Web App" />
												Website or Web App
											</span>
										</ButtonCheckbox>
									</PlatformOptionButton>
									</Buttons>
									{platformsError && (
										<div className="ant-form-item-explain-error">
											{platformsError}
										</div>
									)}
								</PlatformOptionButtons>
								{hasAnyApps && (
									<PlatformOptionInputs>
										{!!hasMobileApp && (
											<InputWrapper>
												<TextInput
													name="mobileAppsList"
													maxLength={333}
													ariaLabel='app selection input'
													placeholder='Enter app name(s)'
													rules={[{
														validator: (_, value) => {
															setMobileAppError(null)
															if (!value?.length) {
																focusInput('mobileAppsList')
																setMobileAppError('This field is required')
																return Promise.reject()
															}
															if (value.length > 333) {
																focusInput('mobileAppsList')
																setMobileAppError('App name should contain at most 333 characters.')
																return Promise.reject()
															}
															if (value.length < 3) {
																focusInput('mobileAppsList')
																setMobileAppError('App name should contain at least 3 characters.')
																return Promise.reject()
															}
															return Promise.resolve()
														}
													}]}
												/>
												{mobileAppError && (
													<div className="ant-form-item-explain-error">
														{mobileAppError}
													</div>
												)}
											</InputWrapper>
										)}
										{!!hasWebApp && (
											<InputWrapper>
												<TextInput
													name="webDomainsList"
													maxLength={333}
													ariaLabel='app selection input'
													placeholder='Enter website URLs'
													rules={[{
														validator: (_, value) => {
															setWebAppError(null)
															if (!value?.length) {
																focusInput('webDomainsList')
																setWebAppError('This field is required')
																return Promise.reject()
															}
															if (value.length > 333) {
																focusInput('webDomainsList')
																setWebAppError('Website URL should contain at most 333 characters.')
																return Promise.reject()
															}
															if (value.length < 3) {	
																focusInput('webDomainsList')
																setWebAppError('Website URL should contain at least 3 characters.')
																return Promise.reject()
															}
															return Promise.resolve()
														}
													}]}
												/>
												{webAppError && (
													<div className="ant-form-item-explain-error">
														{webAppError}
													</div>
												)}
											</InputWrapper>
										)}
									</PlatformOptionInputs>
								)}
							</PlaformOptionsContainer>
						</FormWrapper>
						<FlowNavButtons
							primaryText="Continue"
							secondaryHandler={handleBack}
							secondaryText='Go back'
							loading={loading}
						/>
					</Form>
				</FlowWrapper>
			</FlowLayout>
		</>
	)
}

export default OrganizationApps