import React from 'react';
import { useSelector } from 'react-redux'
import { LoadingOutlined } from '@ant-design/icons';
import { Spin } from 'antd';

const antIcon = <LoadingOutlined style={{ fontSize: 16 }} spin />
const PendingLoaderInfo = ({ preText, midText = 'data sets', apiCalledTime }) => {
  const [difference, setDifference] = React.useState()
  const { commonReducer } = useSelector((state) => state)
  const checkedApiCalledTime = apiCalledTime || commonReducer.apiCalledTime
  React.useEffect(() => {
    let interval
    if (checkedApiCalledTime) {
      interval = setInterval(() => {
        const newDifference = Math.floor(Date.now() / 1000) - checkedApiCalledTime
        setDifference(newDifference)
      }, 1000)
    }
    return () => clearInterval(interval)
  }, [checkedApiCalledTime])
  return checkedApiCalledTime ? (
    difference >= 5 && (
      <div className='heatmap-loading-message'>
        <label>
          <span>{preText} - </span> large {midText} can take a bit longer to load.
        </label>
        <Spin indicator={antIcon} />
      </div>
    )
  ) : (
    <></>
  )
}
export default PendingLoaderInfo
