import React, { createContext, useContext, useState, useMemo, ReactNode, Dispatch, SetStateAction } from 'react';

interface PageContextType {
  page: number | null;
  setPage: Dispatch<SetStateAction<number | null>>;
}

interface PageDataProviderProps {
  children: ReactNode;
}

const PageContext = createContext<PageContextType>({
  page: null,
  setPage: () => {
    throw new Error('PageContext must be used within a PageDataProvider');
  },
});

export const PageDataProvider = ({ children }: PageDataProviderProps) => {
  const [page, setPage] = useState<number | null>(null);

  const contextValue = useMemo(() => ({
    page,
    setPage,
  }), [page]);

  return (
    <PageContext.Provider value={contextValue}>
      {children}
    </PageContext.Provider>
  );
};

export const usePageState = () => useContext(PageContext);
