import { message } from 'antd';
import Cookies from 'universal-cookie';
import ProfileApi from 'services/profileApi';
import SettingApi from 'services/settingApi';
import { GET_USER } from 'types';
import { getErrorHandle } from './common';

export const gotUser = (data) => ({
  type: GET_USER,
  data,
});

export const getUser = () => async (dispatch) => {
  try {
    const res = await SettingApi.getNewProfile();
    
    if (res.status === 200) {
      const data = res?.data?.data;
      await dispatch(gotUser(data));

      // Set user Identity on UXCam
      try {
        const uxc = window?.uxc
        if (uxc) {
          // eslint-disable-next-line no-underscore-dangle
          uxc.setUserIdentity(res?.data?.data?._id)
          uxc.setUserProperty( 'email', res?.data?.data?.email)
          uxc.setUserProperty( 'name', res?.data?.data?.name)

          const cookies = new Cookies();
          const isImpersonated = cookies.get('loggedInFromAdminDashboard') === '1';
          const loggedInTypeCookie = cookies.get('loggedInType');
          const loggedInType = isImpersonated && (loggedInTypeCookie === 'admin' || loggedInTypeCookie === 'guest')
            ? loggedInTypeCookie
            : 'user';

          uxc.setUserProperty('is_impersonated', isImpersonated);
          uxc.setUserProperty('logged_in_type', loggedInType);
        //   if ( res?.data?.data?.organization && res?.data?.data?.organization?.length > 0 ) {
        //     const restrictedOrgs = [
        //       '600b32209aeb7a484e7d481c'
        //     ]
        //     const orgs = res?.data?.data?.organization?.map(org => org[ '$oid' ] ) || []
        //     const isOrgRestricted = orgs.some( org => restrictedOrgs.includes(org) )
        //     if (isOrgRestricted) {
        //       uxc.abort()
        //     }
        //   }
        }

      } catch (error) {
        // eslint-disable-next-line no-console
        console.log('Error in setting user identity on UXCam', error)
      }

      return data;
    }
    
    // If status is not 200, throw the response
    throw res;
  } catch (error) {
    // Handle the error properly and re-throw it so it can be caught by the caller
    getErrorHandle(dispatch, gotUser, error);
    throw error; // Re-throw so the caller can catch it
  }
};

export const editUserName = (data) => async (dispatch) =>
  ProfileApi.editUserName(data)
    .then(async (res) => {
      await dispatch(getUser());
      message.success('Profile name update successfully.');
      return res.data;
    })
    .catch((err) => {
      err && err.response && message.error(err.response.data.error.name[0]);
      return err.response;
    });

export const uploadImage = (data) => (dispatch, getState) => {
  const profile = getState().profileReducer;
  profile.profilePicture = data;
  dispatch(gotUser(profile));

  return profile;
};
export const updatePassword = (data) => () =>
  ProfileApi.updatePassword(data)
    .then((res) => res.data)
    .catch((error) => error.response.data);

export const changeEmail = (data) => () =>
  ProfileApi.profileNewEmail(data)
    .then((res) => res?.data)
    .catch((error) => error?.response?.data);

export const updateImage = (data) => () =>
  ProfileApi.uploadImage(data)
    .then((res) => res?.data)
    .catch((error) => error?.response?.data);

export const updateProfileInformation = (data) => async (dispatch) =>
  SettingApi.updateProfileInfo(data)
    .then(async (res) => {
      message.success('Profile information updated successfully.');
      await dispatch(getUser());
      return res.data;
    })
    .catch((err) => {
      message.error(
        err?.response?.data?.error?.organizationRole ||
          'Unable to update organization role'
      );
      return err.response;
    });

export const updateProfileRemindLater = () => () =>
  SettingApi.updateProfileRemindMeLater()
    .then((res) => res.data)
    .catch((err) => err.response);
