import React, { createContext, useContext, useState, useMemo, useCallback, ReactNode } from 'react';

export interface FormData {
  mobileAppsList: string;
  webDomainsList: string;
  matterResp: string[];
  companySize: string | null;
  highFit: boolean;
  achievements: string[];
  fullName: string;
  department: string;
  jobTitle: string;
  organizationName: string;
  phone: string;
  referringPartnerVal: string | null;
  email: string;
}

interface FormDataContextType {
  formData: FormData;
  setValues: (values: Partial<FormData>) => void;
}

const formInitialData: FormData = {
  mobileAppsList: '',
  webDomainsList: '',
  matterResp: [],
  companySize: null,
  highFit: false,
  achievements: [],
  fullName: '',
  department: '',
  jobTitle: '',
  organizationName: '',
  phone: '',
  referringPartnerVal: null,
  email: '',
};

const FormDataContext = createContext<FormDataContextType>({
  formData: formInitialData,
  setValues: () => {
    // Default no-op function
  },
});

interface FormDataProviderProps {
  children: ReactNode;
}

export const FormDataProvider = ({ children }: FormDataProviderProps) => {
  const [formData, setFormData] = useState<FormData>(formInitialData);

  const setValues = useCallback((values: Partial<FormData>) => {
    setFormData((prevData) => ({
      ...prevData,
      ...values,
    }));
  }, []);

  const contextValue = useMemo(() => ({
    formData,
    setValues,
  }), [formData, setValues]);

  return (
    <FormDataContext.Provider value={contextValue}>
      {children}
    </FormDataContext.Provider>
  );
};

export const useFormData = () => useContext(FormDataContext);
