import { getCookie } from "./getCookies"

const submitForm = (fields, formId) => {
  const hutk = getCookie("hubspotutk")
  const formattedFields = Object.entries(fields).map(elem => ({
    name: elem[0],
    value: elem[1],
  }))

  return fetch(`https://api.hsforms.com/submissions/v3/integration/submit/5081481/${formId}`, {
    method: "POST",
    mode: "cors",
    headers: {
      "Content-Type": "application/json",
    },
    body: JSON.stringify({
      fields: formattedFields,
      context: {
        hutk, // include this parameter and set it to the hubspotutk cookie value to enable cookie tracking on your submission
      },
      legalConsentOptions: {
        consent: {
          // Include this object when GDPR options are enabled
          consentToProcess: true,
          text: "I agree to allow UXCam to store and process my personal data.",
          communications: [
            {
              value: true,
              subscriptionTypeId: 999,
              text: "I agree to receive marketing communications from UXCam.",
            },
          ],
        },
      },
    }),
  })
    .then(resp => resp)
    .catch(err => { throw new Error("Error", { cause: err }) })
}

const hubspot = { submitForm }

export default hubspot
