import React, { useEffect, useRef, useState, memo, useCallback, ChangeEvent } from 'react';

// packages
import styled, { css } from 'styled-components';

// components
import { Form, Input } from 'antd';
import { Rule } from 'antd/es/form';

const FormItem = Form.Item;

// styles
const InputWrapper = styled.div`
  position: relative;

  .ant-input-suffix {
    position: absolute;
    top: 50%;
    right: 32px;
    transform: translateY(-50%);
  }
`;

const InputStyled = styled(Input)`
  position: relative;
  font-size: 14px;
  line-height: 132%;
  font-family: 'Roboto', sans-serif;
  letter-spacing: 0.01em;
  padding: 13px 16px;
  border: none;
  font-weight: 400;
  border-radius: 8px;
  transition: all 0.1s ease-in-out;
  color: #161E35;
  background-color: #F3F4F5;
  border: 1px solid transparent;
  &[data-is-phone='true'] {
    padding-left: 27px;
  }
  &[disabled] {
    background-color: #F8F8F9;
  }
  &::placeholder {
    color: #A2A5AE;
    font-weight: lighter;
  }
  &.ant-input-status-error {
    border: 1px solid transparent !important;
    background-color: #F3F4F5 !important;
  }
  &:focus, &:active, &.ant-input-status-error:focus, &.ant-input-status-error:active {
    background-color: #EFF5FF !important;
    border-color: #5D97FF !important;
  }
`;

const FormItemStyled = styled(FormItem)`
  position: relative;
  .ant-form-item-control-input-content {
    display: flex;
    flex-direction: column;
  }

  .ant-form-item-label {
    pointer-events: none;
  }

  .ant-input-status-error:not(.ant-input-disabled):not(.ant-input-borderless).ant-input:focus,
  .ant-input-status-error:not(.ant-input-disabled):not(.ant-input-borderless).ant-input-focused,
  .ant-input-status-error:not(.ant-input-disabled):not(.ant-input-borderless).ant-input,
  .ant-input-status-error:not(.ant-input-disabled):not(.ant-input-borderless).ant-input:hover {
    box-shadow: none;
    border-color: rgb(192, 202, 217);
  }

  label {
    color: #5B6D89;
    font-weight: lighter;
  }

  .ant-col.ant-form-item-label,
  label {
    transition: all 0.1s ease-in-out;
  }

  .ant-col.ant-form-item-label {
    position: absolute;
    top: 23px;
    left: 16px;
    transform: translateY(-50%);
    z-index: 99;
    padding: 0;
    > label::before {
      display: none;
    }
    > label::after {
      display: none;
    }
  }

  &:focus-within .ant-col.ant-form-item-label {
    top: 10px;
    > label {
      font-size: 10px;
      line-height: 10px;
      color: #5d97ff;
    }
  }

  &[data-has-value='true']:not(:focus-within) .ant-col.ant-form-item-label {
    opacity: 0;
    top: 15px;
    > label {
      font-size: 10px;
      line-height: 10px;
    }
  }

  &[data-is-phone='true'] {
    &::before {
      content: '+';
      position: absolute;
      left: 16px;
      top: 11px;
      color: #A2A5AE;
      font-size: 14px;
      z-index: 1;
      font-weight: 300;
    }
    &[data-has-value='true'] {
      &::before {
        color: #161E35;;
      }
    }
  }
`;

const Label = styled.label`
  font-size: 14px !important;
  line-height: 22px !important;
  margin-bottom: 8px !important;
  font-family: 'Roboto', sans-serif !important;
  color: #161E35;
  align-self: flex-start;
  @media (max-width: 768px) {
    font-size: 18px !important;
  }
`;

const InputContainer = styled.div`
  text-align: left;
  display: flex;
  flex-direction: column;
  &[aria-hidden='true'] {
    display: none;
  }
  .ant-form-item {
    transition: margin-bottom 0s ease-in-out;
    margin-bottom: 24px !important;
  }
  &[data-has-error='true'] {
    .ant-form-item {
      margin-bottom: 8px !important;
    }
  }
  &[data-no-margin='true'] {
    .ant-form-item {
      margin-bottom: 0 !important;
    }
  }
`;

export const Components = {
  InputWrapper,
  InputStyled,
  FormItemStyled,
  Label,
  InputContainer,
}

export interface TextInputProps {
  name: string;
  placeholder?: string;
  rules?: Rule[];
  label?: string;
  isPhone?: boolean;
  value?: string;
  onInputChange?: (event: ChangeEvent<HTMLInputElement>) => void;
  ariaLabel?: string;
  disabled?: boolean;
  maxLength?: number;
  hidden?: boolean;
  hasError?: boolean;
  validateTrigger?: string | string[];
  type?: string;
  noMargin?: boolean;
  onKeyDown?: (e: React.KeyboardEvent<HTMLInputElement>) => void
}

const TextInput: React.FC<TextInputProps> = ({ 
  name, 
  placeholder, 
  rules, 
  label,
  isPhone,
  value, 
  onInputChange, 
  ariaLabel, 
  disabled, 
  maxLength, 
  hidden = false, 
  hasError = false,
  validateTrigger,
  type = 'text',
  noMargin = false,
  onKeyDown,
}) => {
  const [hasValue, setHasValue] = useState(false);
  const inputRef = useRef<any>(null);

  const onChange = useCallback(
    (event: ChangeEvent<HTMLInputElement>) => {
      if (event.target.value) {
        setHasValue(true);
      } else {
        setHasValue(false);
      }
      if(onInputChange){
        onInputChange(event)
      }
    },
    [onInputChange],
  )
  

  useEffect(() => {
    if (inputRef.current?.input?.value) {
      setHasValue(true);
    }
  }, []);

  return (
    <InputContainer
      aria-hidden={ hidden }
      data-has-error={hasError}
      data-no-margin={noMargin}
    >
      {label && <Label htmlFor={name}>{label}</Label>}
      <InputWrapper>
        <FormItemStyled
          rules={ hidden ? undefined : rules }
          name={name}
          data-has-value={hasValue}
          validateTrigger={validateTrigger}
          data-is-phone={isPhone}
        >
          <InputStyled
            id={name}
            onChange={onChange}
            ref={inputRef}
            placeholder={placeholder}
            value={value}
            aria-label={ariaLabel}
            disabled={disabled}
            maxLength={maxLength}
            minLength={3}
            name={name}
            type={type}
            data-is-phone={isPhone}             
            onKeyDown={onKeyDown}
          />
        </FormItemStyled>
      </InputWrapper>
    </InputContainer>
  );
};

export default memo(TextInput);
