export class Color {
	r = 0;

	g = 0;

	b = 0;

	a = 0;

	constructor( ...args: ( number | string )[] ) {

		const arg0 = args[ 0 ]

		if ( typeof arg0 === 'string' && arg0.charAt( 0 ) === '#' ) {
			const [
				r,
				g,
				b,
			] = [
				arg0.slice( 1, 3 ),
				arg0.slice( 3, 5 ),
				arg0.slice( 5, 8 ),
			]
				.map( Color.parseHex )

			this.r = r
			this.g = g
			this.b = b
			this.a = 1
			return
		}

		const [ r, g, b, a = 1 ] = args

		this.r = r as number
		this.g = g as number
		this.b = b as number
		this.a = a as number

	}

	toString(): string {
		const {
			r, g, b, a,
		} = this
		return `rgba( ${ r }, ${ g }, ${ b }, ${ a } )`
	}

	toURI(): string {
		return encodeURIComponent( this.toString() )
	}

	alpha( a: number ): Color {
		const {
			r, g, b,
		} = this
		return new Color( r, g, b, a )
	}

	shade( amt: number ): Color {
		let {
			r,
			g,
			b,
		} = this
		const {
			a,
		} = this

		r += amt;

		if ( r > 255 ) r = 255;
		else if ( r < 0 ) r = 0;

		b += amt;

		if ( b > 255 ) b = 255;
		else if ( b < 0 ) b = 0;

		g += amt;

		if ( g > 255 ) g = 255;
		else if ( g < 0 ) g = 0;

		return new Color( Math.round( r ), Math.round( g ), Math.round( b ), a )
	}

	static parseHex = ( hex: string ): number => parseInt( hex, 16 )
}
