/* eslint-disable camelcase */
import React, { memo, useRef, useState } from 'react';
import { useDispatch } from 'react-redux';

// packages
import axios from 'axios';
import styled from 'styled-components';
import ReCAPTCHA from 'react-google-recaptcha';

// components
import { Form, message, Select } from 'antd';

// utils
import hubspot from 'Utils/helpers/hubspot';
import { getCountryRegion, handleErrorMessage } from 'Utils/helpers/commonUtils';
import { SectionHeader, SelectWrapper, ChevronDown } from 'components/features/onboard/FlowScreens/common'
import redirectUrlHandler from 'Utils/helpers/redirectUrlHandler';
import { rollbar } from 'components/common/rollbar';
import { trackPageViews } from 'redux/actions/trackingReport';

import FlowLayout from "../../FlowLayout";
import FlowNavButtons from '../../FlowNavButtons';
import TextInput from '../../TextInput';

// context
import { usePageState } from '../../context/signupPages.context';
import { useFormData } from '../../context/signupFlowData.context';
import { selectStyles, GlobalStyles } from '../NameJobPhone';
import { focusInput } from '../OrganizationApps';


const FormStyled = styled(Form)`
  width: 100%;
  margin-top: 25px;
`

// regex that allows alphabets (A-Z, a-z), numbers (0-9), dash (-), underscore (_), apostrophe ('), chinese chars and spaces:
export const nameRegex = /^[\p{L}\p{N}\p{Pd}_'\s\u4E00-\u9FFF]+$/u;

export const uxcamRefOptions = [
  {
    value: 'AI Chat',
    label: 'AI Chat',
  },
  {
    value: 'Colleague',
    label: 'Colleague',
  },
  {
    value: 'Friend',
    label: 'Friend',
  },
  {
    value: 'Reddit',
    label: 'Reddit',
  },
  {
    value: 'Google Search',
    label: 'Google Search',
  },
  {
    value: 'Other',
    label: 'Other',
  },
]

interface FormData {
  hearAboutUs: string;
  other?: string;
  organization?: string;
  phone?: string;
}

interface IProps {
  token?: string;
  secret?: string;
  redirectUrl?: string;
  isValidRedirectUrl?: boolean;
  isEmailInvitation?: boolean;
  invitation_token?: string;
}

const Source = (props: IProps) => {
  const [form] = Form.useForm<FormData>();
  const dispatch = useDispatch();

  const {
    token,
    secret, 
    redirectUrl, 
    isValidRedirectUrl, 
    isEmailInvitation,
    invitation_token,
  } = props;

  const { setPage } = usePageState();
  const { formData, setValues } = useFormData();


  const [isLoading, setIsLoading] = useState(false)

  let cancel: ((reason?: string) => void) | null = null;
  let request = 0;

  const {CancelToken} = axios;
  const recaptchaRef = useRef<ReCAPTCHA | null>(null);

  const SourceValue = Form.useWatch('hearAboutUs', form);

  const shouldFocusOnFirstInput = React.useRef(true)
  React.useEffect(() => {
    if (shouldFocusOnFirstInput?.current) {
      focusInput('[id="hearAboutUs"]', true)
      shouldFocusOnFirstInput.current = false
    }
  }, [])

  const onFinish = async (value: FormData): Promise<boolean | void> => {
    let postData: Record<string, unknown> = {}
    setIsLoading(true);

    request+=1;
    if(cancel){
      cancel(`Request ${request}`)
    }

    const captchaToken = await recaptchaRef.current?.executeAsync()
    
    let region: string;
    if (process.env.NODE_ENV === 'development') {
      region = 'EMEA'
    } else {
      region = await getCountryRegion() || 'EMEA'
    }

    postData = {
      email: formData.email,
      name: formData.fullName,
      companyName: formData.organizationName,
      department: formData.department,
      phone: formData.phone,
      selfServeCheckout: region === "APAC" ? !formData.highFit : false,
      captchaToken,
      ...(isEmailInvitation && {'duplicateSignupKey': invitation_token} ),
      ...(token && {'token': token}),
      ...(secret && {'secret': secret}),
    }
    await axios({
      method: 'post',
      url: `${process.env.AUTH_API_URL}/user/signup/quick`,
      data: postData,
      withCredentials: true,
      cancelToken: new CancelToken((c: (reason?: string) => void)=> {
        cancel = c;
        request = 0;
      })
    }).then(async (response) => {
      await hubspot.submitForm({
        email: formData.email,
        how_did_you_hear_about_uxcam___dropdown: value.hearAboutUs,
        how_did_you_hear_about_uxcam_: value.other || '',
      }, process.env.FLOW_ORGANIZATION_ID)
      .catch((err) => rollbar.error(err))

      window.dataLayer = window.dataLayer || [];

      window.dataLayer.push({
        event: 'Sign Up Complete',
      });

      if ( formData.mobileAppsList && formData.mobileAppsList?.length === 0 ) {
        window.dataLayer.push({
          event: 'Sign Up Complete - Checkbox app has not been released yet is checked',
        });
      }

      window.dataLayer.push({
        event: 'formSubmissionSuccess',
        formId: 'registration-form',
        signupEmail: formData.email,
        userID: response?.data?.data?.customer?.id,
        orgID: response?.data?.data?.organization?.id,
      });

      setIsLoading(false);
      cancel = null;

      if(redirectUrl && isValidRedirectUrl){
        return redirectUrlHandler(redirectUrl);
      }
      setValues({
        organizationName: value.organization || formData.organizationName,
        phone: `+${value.phone || formData.phone}`,
      });

      const eventCaptchaToken = await recaptchaRef.current?.executeAsync()
      dispatch(trackPageViews(null, {
        eventName: 'wa_signup_source_submitted',
        eventProperty: {
          email: formData?.email || '',
          source: SourceValue || '',
          other: SourceValue === 'Other' ? form.getFieldValue('other') || '' : '',
        },
      }, eventCaptchaToken ))

      if(invitation_token){
        window.location.href = `${process.env.REDIRECT_URL}/dashboard`;
      } else {
        setPage(4); // set to ThankYou page
      }

      return true;
    }).catch((error) => {      
      cancel = null;
      if (error.response) {
        rollbar.error(`SIGN UP ERROR with error response: ${JSON.stringify(error.response.data, null, 2)}`)
        handleErrorMessage(error.response)
      }else{
        rollbar.error('SIGN UP ERROR:',error)
        message.error('Something went wrong. Please try again later.')
      }
    }).finally(() => {
      setIsLoading(false)
    })

  };

  return (
    <>
      <ReCAPTCHA
        ref={recaptchaRef}
        size="invisible"
        sitekey={process.env.SITE_KEY || ''}
      />
      <FlowLayout
        title="One last thing."
        progress={100}
        hideLogos
      >
        <GlobalStyles />
        <FormStyled
          form={form}
          noValidate
          validateTrigger={['onSubmit']}
          onFinish={(values) => onFinish(values as FormData)}
          initialValues={{
            hearAboutUs: SourceValue,
            other: SourceValue === 'Other' ? form.getFieldValue('other') : undefined,
          }}
        >
          <SelectWrapper>
            <SectionHeader>How did you hear about UXCam?</SectionHeader>
            <Form.Item
              name="hearAboutUs"
              rules={[
                {
                  required: true,
                  message: 'Please select an option',
                }
              ]}
            >
              <Select
                placeholder="Select an option"
                style={selectStyles}
                options={uxcamRefOptions}
                suffixIcon={<ChevronDown />}
                onChange={() => form.setFieldsValue({ other: '' })}
              />
            </Form.Item>
          </SelectWrapper>
          <Form.Item 
            name="other" 
            style={{ display: SourceValue === 'Other' ? 'block' : 'none' }}
            rules={[
              { validator: (_, value) => {
                if (SourceValue === 'Other' && !value?.length) {
                  return Promise.reject(new Error('Please provide the source of your referral'));
                }
                return Promise.resolve();
              } }
            ]}
          >
              <SectionHeader>Other</SectionHeader>
              <TextInput
                name="other"
                placeholder="Example: Through a colleague"
              />
          </Form.Item>
          <ReCAPTCHA
            ref={recaptchaRef}
            size="invisible"
            sitekey={process.env.SITE_KEY || ''}
          />
          <FlowNavButtons
            primaryText="Complete sign up"
            secondaryText="Go Back"
            loading={isLoading}
          />
        </FormStyled>
      </FlowLayout>
    </>
  );
};

export default memo(Source);