import React, { memo, useCallback, useMemo, useState } from 'react';

// packages
import { isEmpty } from 'lodash';
import styled, { createGlobalStyle } from 'styled-components';

// components
import { Form, Select } from 'antd';

import { departmentOptions } from 'components/common/UpdateRoleModal';
import { SectionHeader, SelectWrapper, ChevronDown } from 'components/features/onboard/FlowScreens/common';

// utils
import hubspot from 'Utils/helpers/hubspot';
import { rollbar } from 'components/common/rollbar';
import { trackPageViews } from 'redux/actions/trackingReport';
import { useDispatch } from 'react-redux';
import ReCAPTCHA from 'react-google-recaptcha';

// context
import { useFormData } from '../../context/signupFlowData.context';
import { usePageState } from '../../context/signupPages.context';

import TextInput from '../../TextInput';
import FlowLayout from '../../FlowLayout';
import FlowNavButtons from '../../FlowNavButtons';
import { focusInput } from '../OrganizationApps';

export const GlobalStyles = createGlobalStyle`
  .ant-select-dropdown {
    border-radius: 8px;
    box-shadow: none;
    border: 1px solid #E8E8EB;
    padding: 0;
    .ant-select-item {
      font-family: Roboto;
      font-weight: 400;
      font-style: Regular;
      font-size: 14px;
      line-height: 132%;
      letter-spacing: 1%;
      color: #161E35;
      padding: 16px;
      &:hover {
        background-color: #EFF5FF;
      }
      &.ant-select-item-option-selected {
        color: #5D97FF;
      }
    }
  }
`;

const FormStyled = styled(Form)`
  width: 100%;
  margin-top: 18px;
`;

export const selectStyles = {
  // background: 'white',
  border: 'none',
  width: '100%',
  textAlign: 'left' as const,
};

interface FormData {
  name: string;
  flow_department: string;
  phone: string;
}

interface AuthData {
  _formData?: {
    step_1_data?: {
      email: string;
    };
  };
}

interface IProps {
  _auth: AuthData;
}

const NameJobPhone = (props: IProps) => {
  const [form] = Form.useForm<FormData>();
  const dispatch = useDispatch();
  const recaptchaRef = React.useRef<ReCAPTCHA>(null)
  const { _auth: auth } = props;
  const signupData = !isEmpty(auth) ? auth['_formData'] : {} ;
  const email = signupData?.step_1_data?.email;
  const API_ID = process.env.FLOW_DEPARTMENT_ID;

  const { setPage } = usePageState();
  const { formData, setValues } = useFormData();

  const [isLoading, setIsLoading] = useState(false);

  const shouldFocusOnFirstInput = React.useRef(true)
  React.useEffect(() => {
    if (shouldFocusOnFirstInput?.current) {
      focusInput('name')
      shouldFocusOnFirstInput.current = false
    }
  }, [])

  const onFinish = useCallback(
    async (value: FormData) => {
      setIsLoading(true);
      setValues({
        fullName: value.name,
        department: value.flow_department,
        phone: value.phone || formData.phone,
      });
      const token = await recaptchaRef.current?.executeAsync()
      dispatch(trackPageViews(null, {
        eventName: 'wa_signup_personal_submitted',
        eventProperty: {
          email: email || formData?.email || '',
          orgName: formData?.organizationName || '',
          name: value?.name || '',
          department: value?.flow_department || '',
          phoneNumber: value?.phone || '',
        },
      }, token ))

      hubspot
        .submitForm(
          {
            full_name: value.name,
            department: value.flow_department,
            phone: value.phone || formData.phone,
            email: email || formData?.email || '',
          },
          API_ID
        )
        .catch((err) => rollbar.error(err))
        .finally(() => setIsLoading(false));

        setPage((currentPage) => (currentPage || 0) + 1);
    },
    [API_ID, email, setPage, setValues, formData, dispatch]
  );

  const SelectOptions = useMemo(() => departmentOptions, []);

  return (
    <>
      <ReCAPTCHA
        ref={recaptchaRef}
        size="invisible"
        sitekey={process.env.SITE_KEY || ''}
      />
      <GlobalStyles />
      <FlowLayout
        title="Tell us a bit about you."
        progress={66}
        hideLogos
      >
        <FormStyled
          form={form}
          onFinish={onFinish as any}
          validateTrigger={['onSubmit']}
          noValidate
          initialValues={{
            name: formData.fullName,
            flow_department: formData.department || undefined,
            phone: formData.phone,
          }}
        >
          <SectionHeader>Enter your name</SectionHeader>
          <TextInput
            placeholder="Your full name"
            name="name"
            rules={[
              {
                required: true,
                message: 'Your name is required',
              },
              {
                min: 3,
                message: 'Name must be at least 3 letters',
              },
            ]}
          />
          <SelectWrapper>
            <SectionHeader>Select your department</SectionHeader>
            <Form.Item
              name="flow_department"
              rules={[
                {
                  required: true,
                  message: 'Your department is required',
                },
              ]}
            >
              <Select
                placeholder="Select a department"
                style={selectStyles}
                options={SelectOptions}
                suffixIcon={<ChevronDown />}
              />
            </Form.Item>
          </SelectWrapper>
          <SectionHeader>Enter your phone number</SectionHeader>
          <TextInput
            isPhone
            rules={[
              {
                required: true,
                message: 'Your phone number is required',
              },
              {
                pattern: /^[1-9][0-9 \-(\\).]{7,15}$/,
                message:
                  'Please enter a valid phone number starting with a country code',
              },
            ]}
            name="phone"
            placeholder="Your contact number"
            maxLength={15}
          />
          <FlowNavButtons
            primaryDisabled={isLoading}
            primaryText="Continue"
            secondaryText="Go Back"
          />
        </FormStyled>
      </FlowLayout>
    </>
  );
};

export default memo(NameJobPhone);