import React, { memo, useCallback } from 'react';

// packages
import styled from 'styled-components';

// components
import { Button } from 'antd';

// context
import { usePageState } from '../context/signupPages.context';

// types
interface FlowNavButtonsProps {
  primaryText?: string;
  primaryDisabled?: boolean;
  secondaryText?: string;
  secondaryDisabled?: boolean;
  primaryHandler?: () => void;
  secondaryHandler?: () => void;
  disabled?: boolean;
  loading?: boolean;
}

const PrimaryButton = styled(Button)`
  height: fit-content;
  padding: 10px 24px !important;
  border-radius: 6px !important;
  box-shadow: none !important;
  font-size: 18px !important;
  line-height: 28px !important;
  font-family: 'Poppins', sans-serif !important;
  font-weight: 500 !important;
  letter-spacing: -0.02em !important;
  background-color: #5D97FF;
  :hover:not(:disabled) {
    background: #161e35;
    border-color: #161e35;
  }
`

// styles
const SecondaryButton = styled.button`
  color: #5d97ff;
  background-color: transparent !important;
  border: none;
  box-shadow: none;
  margin-top: 16px;
  font-weight: lighter;
  font-size: 14px !important;
  line-height: 132% !important;
  cursor: pointer;
  letter-spacing: 0.01em;
  font-family: 'Roboto', sans-serif;
  &:disabled{
    opacity: 0.6;
  }
`;

const Wrapper = styled.div`
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  margin-top: 8px;
`;

const primaryBtnStyle = {
  borderRadius: 4,
  fontFamily: 'Poppins',
  fontSize: 18,
  padding: '20px 24px',
  alignItems: 'center',
  display: 'flex',
  transition: 'all 0.4s ease',
};

const FlowNavButtons = ({
  primaryText,
  primaryDisabled,
  secondaryText,
  secondaryDisabled,
  primaryHandler,
  secondaryHandler,
  disabled,
  loading,
}: FlowNavButtonsProps) => {
  const { setPage } = usePageState();

  const handleSecondaryClick = useCallback(
    () => {
      if (secondaryText === 'Go Back' || secondaryText === 'Go back' && !secondaryHandler) {
        return setPage((page) => (page || 0) - 1);
      }
      return secondaryHandler?.();
    },
    [secondaryHandler, secondaryText, setPage],
  )


  return (
    <Wrapper>
      {primaryText && (
        <PrimaryButton
          onClick={primaryHandler}
          htmlType="submit"
          type="primary"
          style={primaryBtnStyle}
          disabled={primaryDisabled || disabled || loading}
          loading={loading}
        >
          {primaryText}
        </PrimaryButton>
      )}
      {secondaryText && (
        <SecondaryButton onClick={handleSecondaryClick} type="button" disabled={secondaryDisabled}>
          {secondaryText}
        </SecondaryButton>
      )}
    </Wrapper>
  );
};

export default memo(FlowNavButtons);
