import { omit } from 'lodash';
import Cookies from 'universal-cookie';
import eventTrackApi from 'services/globalInstance';
import { mappedSegmentType, removeValuesFromFilters } from 'Utils/helpers/commonUtils';
import { FeatureList, isLocal } from 'Utils/constants/variables';
import { rollbarTracking } from 'components/common/rollbar';

const browserCookies = new Cookies();

export const getUTMParams = () => {
  const url = new URL(window.location.href);
  const utmSource = url.searchParams.get('utm_source');
  const utmMedium = url.searchParams.get('utm_medium');
  const utmContent = url.searchParams.get('utm_content');
  const utmTerm = url.searchParams.get('utm_term');
  const utmParams = {
    name: url.hostname,
    source: utmSource || '',
    medium: utmMedium || '',
    content: utmContent || '',
    term: utmTerm || '',
  };
  return JSON.stringify(utmParams);
};

export const getFeatureCategory = (urlQ) => {
  const { parentType, setting } = urlQ || {};
  const settingType = parentType === 'settings' ? `${setting}` : parentType;
  let categoryType = mappedSegmentType[parentType];
  if (categoryType === 'heatmap') {
    categoryType = 'screen';
  }

  const featureCategory = mappedSegmentType[parentType]
    ? `${categoryType}${
        ['screenFlow', 'screenBurst'].indexOf(mappedSegmentType[parentType]) >
        -1
          ? ''
          : 's'
      }`
    : settingType;
  return featureCategory;
};
 
export const trackPageViews = (profileArgs, events, captchaToken) => async (_, getState) => {

  const loggedInFromAdminDashboard = browserCookies.get(
    'loggedInFromAdminDashboard'
  );
  const {
    currentAppReducer: currentApp,
    currentOrgReducer: currentOrg,
    applicationReducer: appReducer,
    urlReducer: urlQ,
    profileReducer: profiles,
    appFilter,
  } = getState()

  const profile = profiles || profileArgs;
  const { parentType, appId, org: orgId, url, sessionid, app_tab } = urlQ || {};
  const { status } = currentOrg;
  const isPublic = captchaToken && !Object.keys(currentOrg || {})?.length && !Object.keys(currentApp || {})?.length && !appReducer?.length && !Object.keys(profiles || {})?.length;

  if (['dashboard', 'shareSession'].includes(parentType)) return;
  const appWithSubscription = appReducer?.find(
    (appWithSub) => appWithSub.orgId === currentApp.orgId
  );

  const { _id: subscriptionId, type: planType, assignedPlanId } =
    appWithSubscription?.subscription || {};

  // @NOTE: Adding a first plan type because there is no currentApp in case of first signup and app creation form
  const firstPlanType = appReducer?.[0]?.subscription?.type;
  const firstOrgId = appReducer?.[0]?.orgId;
  if (!isPublic && !planType && !firstPlanType) {
    rollbarTracking.error(`[${process.env.APP_ENV}] No plan type received from API`, {
      subscriptionId,
      appId,
      orgId,
      assignedPlanId
    });
    return;
  }

  try {
    const splitUrl = url && url.split('/');
    const filters = mappedSegmentType[parentType]
      ? appFilter[mappedSegmentType[parentType]].segment
      : [];
    let propsList = omit(
      {
        ...urlQ,
        ...(filters.length && {
          filters: removeValuesFromFilters(filters),
        }),
      },
      'appId',
      'url',
      'parentType',
      'type',
      'index',
      'video'
    );
    propsList = Object.values(propsList).reverse();

    const featureCategory = getFeatureCategory(urlQ);
    const splitType =
      splitUrl && splitUrl[4] ? splitUrl[4].replace(/\?.*$/g, '') : '';
    const feature = parentType === 'settings' ? app_tab :
      FeatureList.includes(parentType)
      ? parentType
      : splitType.length > 15
      ? 'list'
      : splitType; // when the url does not contain the list in the pages , we need to add it manually

    let ipaddress = 'could not track'
    let sourceId = ''

    try {
      ipaddress = localStorage.getItem('internetIdentity') ?? 'could not track'
      sourceId = sessionStorage.getItem('source_id')
    } catch (err) {
      // silent fail
    }

    let eventPayload = {
      sessionid: sessionid || '',
      email: (isPublic ? events?.eventProperty?.email : profile?.email ) || '',
      title: document.title,
      ipaddress,
      campaign: getUTMParams(),
      featurecategory: featureCategory,
      feature,
      referrer: loggedInFromAdminDashboard ? 'https://admin.uxcam.com/' : '',
      useragent: window.navigator.userAgent,
      props_list: propsList,
      userlocaltime: new Date().toLocaleString('sv-SE'),
      timezone: Intl.DateTimeFormat().resolvedOptions().timeZone,
      app_id: appId || currentApp['_id'],
      org_id: orgId || currentApp.orgId || firstOrgId,
      isintegrated: currentApp.isIntegrated || false,
      plan_type: planType || firstPlanType,
      subscriptionid: subscriptionId,
      subscription_status: status || '',
      assignedPlanId,
      source_id: sourceId,
    };

    if (events) {
      const { track_type, eventProperty, extraPayload = {} } = events;
      eventPayload.track_type = track_type;
      eventPayload.eventproperty = eventProperty;
      eventPayload = {...eventPayload, ...extraPayload}
    }

    const eventName = `${
      events ? events?.eventName : `screenvisit_${featureCategory}`
    }`;

    const newPayload = {
      event_name: eventName,
      properties: eventPayload,
      ...(isPublic && {
        captcha_token: captchaToken,
      }),
    };

    if ( typeof window !== 'undefined' && window.uxc) {
      window.uxc.event(eventName, eventPayload);
    }

    if (isPublic) {
      await eventTrackApi.publicEventTrackPageView(newPayload);
    }else{
      await eventTrackApi.eventTrackPageView(newPayload);
    }
    
  } catch (error) {
    const featureCategory = getFeatureCategory(urlQ);
    const eventName = `${
      events ? events?.eventName : `screenvisit_${featureCategory}`
    }`;
    
    if (!isLocal) {
      rollbarTracking.error(`[${process.env.APP_ENV}] Error in IDH event tracking API`, {
        event_name: eventName,
        appId,
        url,
        error,
      });
    }
  }
};
